INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 0, 0, "", 15, 30000, 24001, 35, 0, 1, "");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 0, 0, "", 1, 40000, 91002, 36, 0, 100, "");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107501, 1, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 1, 40001, 91002, 37, 0, 150, "ぺコリーヌ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107601, 1, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 2, 40001, 91002, 38, 0, 150, "コッコロ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107801, 1, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 3, 40001, 91002, 39, 0, 150, "キャル");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107701, 1, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 4, 40001, 91002, 40, 0, 150, "スズメ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107901, 1, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 5, 40001, 91002, 41, 0, 150, "タマキ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107501, 2, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 6, 40001, 91002, 42, 0, 150, "ぺコリーヌ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107601, 2, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 7, 40001, 91002, 43, 0, 150, "コッコロ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107801, 2, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 8, 40001, 91002, 44, 0, 150, "キャル");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107701, 2, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 9, 40001, 91002, 45, 0, 150, "スズメ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 107901, 2, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 10, 40001, 91002, 46, 0, 150, "タマキ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (8, 0, 0, "", 1, 40003, 91002, 57, 0, 150, "");
