INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 125801, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 40011, 24001, 321, 0, 1, "リリ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 126001, 1, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2, 40011, 24001, 322, 0, 1, "クリア");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 126101, 1, "んーと。\nこれ、あげる。\nはい", 3, 40011, 24001, 323, 0, 1, "プレシア");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 125801, 2, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 4, 40011, 24001, 324, 0, 1, "リリ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 126001, 2, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 5, 40011, 24001, 325, 0, 1, "クリア");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (2, 126101, 2, "お兄。\nきてくれて、うれしい", 6, 40011, 24001, 326, 0, 1, "プレシア");
